<?php
require_once __DIR__.'/../../includes/layout.php';require_role(['Super Admin']);check_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try {
    $action=(string)($_POST['action']??'');$name=trim((string)($_POST['name']??''));$id=(int)($_POST['id']??0);
    if(strlen($name)<3||strlen($name)>80)throw new InvalidArgumentException('Use a name of 3–80 characters.');
    if($action==='office') {
        $reviewer=(int)($_POST['reviewer_id']??0)?:null;
        if($reviewer&&!scalar('SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND u.status="Active" AND r.name IN("Admin","Super Admin","Teacher")',[$reviewer]))throw new InvalidArgumentException('Choose an active staff reviewer.');
        if($id)db()->prepare('UPDATE campus_offices SET name=?,reviewer_id=?,active=? WHERE id=?')->execute([$name,$reviewer,isset($_POST['active'])?1:0,$id]);else db()->prepare('INSERT INTO campus_offices(name,reviewer_id,active) VALUES(?,?,?)')->execute([$name,$reviewer,isset($_POST['active'])?1:0]);
    } elseif($action==='form') {
        $raw=$_POST['route']??[];$route=array_values(array_filter(array_map('intval',is_array($raw)?$raw:explode(',',(string)$raw))));
        if(!$route||count($route)>10||count(array_unique($route))!==count($route))throw new InvalidArgumentException('Choose 1–10 distinct office IDs in approval order.');
        foreach($route as $office)if(!scalar('SELECT COUNT(*) FROM campus_offices WHERE id=? AND active=1',[$office]))throw new InvalidArgumentException('The route must use active office IDs.');
        if($id)db()->prepare('UPDATE campus_form_types SET name=?,route=?,active=? WHERE id=?')->execute([$name,json_encode($route),isset($_POST['active'])?1:0,$id]);else db()->prepare('INSERT INTO campus_form_types(name,route,active) VALUES(?,?,?)')->execute([$name,json_encode($route),isset($_POST['active'])?1:0]);
    }else throw new InvalidArgumentException('Choose an office or form action.');
    log_activity(current_user()['id'],'Workflow configuration updated',$action.' #'.$id);set_flash('success','Workflow configuration saved. Existing request routes are preserved; office reviewer assignments apply immediately.');redirect('workflow_settings.php');
}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(PDOException $e){$error='Unable to save. Check for a duplicate name.';}
$staff=rows('SELECT u.id,u.full_name,r.name AS role FROM users u JOIN roles r ON r.id=u.role_id WHERE u.status="Active" AND r.name IN("Admin","Super Admin","Teacher") ORDER BY u.full_name');$offices=rows('SELECT * FROM campus_offices ORDER BY id');$forms=rows('SELECT * FROM campus_form_types ORDER BY id');render_header('Workflow configuration'); ?>
<div class="page-title"><div><span class="eyebrow">SUPER ADMIN</span><h1>Offices & approval routes</h1><p>Configure the school's offices, assigned reviewers, and approval sequence. Demo routes are examples; confirm actual school policy before use.</p></div></div><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="row g-4"><div class="col-lg-6"><section class="panel"><h2>School offices</h2><?php foreach([...$offices,['id'=>0,'name'=>'','reviewer_id'=>null,'active'=>1]] as $office): ?><form method="post" class="campus-form campus-step"><?= csrf_field() ?><input type="hidden" name="action" value="office"><input type="hidden" name="id" value="<?= (int)$office['id'] ?>"><h3><?= $office['id']?e($office['name']):'New office' ?></h3><label>Office name<input name="name" value="<?= e($office['name']) ?>" class="form-control" maxlength="80" required></label><label>Assigned reviewer<select name="reviewer_id" class="form-select"><option value="">Super Admin review only</option><?php foreach($staff as $person): ?><option value="<?= (int)$person['id'] ?>" <?= (int)$office['reviewer_id']===(int)$person['id']?'selected':'' ?>><?= e($person['full_name'].' · '.$person['role']) ?></option><?php endforeach; ?></select></label><label><input type="checkbox" name="active" <?= $office['active']?'checked':'' ?>> Active for new requests</label><button class="btn btn-outline-primary">Save office</button></form><?php endforeach; ?></section></div><div class="col-lg-6"><section class="panel"><h2>School forms</h2><p>Choose offices in approval order from top to bottom. Leave unused rows blank. Existing requests keep their original route.</p><?php foreach([...$forms,['id'=>0,'name'=>'','route'=>'[]','active'=>1]] as $form): ?><form method="post" class="campus-form campus-step"><?= csrf_field() ?><input type="hidden" name="action" value="form"><input type="hidden" name="id" value="<?= (int)$form['id'] ?>"><label>Form name<input name="name" value="<?= e($form['name']) ?>" class="form-control" maxlength="80" required></label><fieldset><legend>Approval offices in order</legend><div data-approval-route><?php foreach([...json_decode($form['route'],true),0] as $position=>$officeId): ?><label>Approving office <?= $position+1 ?><select name="route[]" class="form-select"><option value="">No office selected</option><?php foreach($offices as $office): ?><option value="<?= (int)$office['id'] ?>" <?= (int)$officeId===(int)$office['id']?'selected':'' ?>><?= e($office['name'].($office['active']?'':' (inactive)')) ?></option><?php endforeach; ?></select></label><?php endforeach; ?></div><button class="btn btn-sm btn-outline-primary mt-2" type="button" data-add-approval>Add another approving office</button></fieldset><label><input type="checkbox" name="active" <?= $form['active']?'checked':'' ?>> Published</label><button class="btn btn-outline-primary">Save school form</button></form><?php endforeach; ?></section></div></div><?php render_footer(); ?>
